def source_ref(source, file, symbol, bundle):
 p=source/'src'/file;lines=p.read_text().splitlines()
 found=[i+1 for i,z in enumerate(lines) if re.search(r'(?:\.proc\s+|^)(?:\:\:)?'+re.escape(symbol)+r'(?:\s|:|$)',z)]
 assert found,(file,symbol);line=found[0]
 q=dict(path=str(p),line=line,symbol=symbol,source_sha256=sha(p),workspace_path=str(ROOT/'src'/file))
 if symbol in bundle['syms']:
  s=bundle['syms'][symbol];q.update(cpu_address=address(bundle,symbol),physical_bank=(location(bundle,symbol)-16)//8192,linked_size=int(s.get('size','0'),0))
 else:q['linked_alias_note']='Scoped/local symbol; source owner linked through exported dispatch'
 return q

