 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--rom',type=Path,required=True);p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--expected-sha256',default=CURRENT);p.add_argument('--native-summary',type=Path);a=p.parse_args()
